def _iter_sims(self) -> Generator[Commonality]:
    """Iterate on similarities among all files, by making a Cartesian
    product.
    """
    min_lines = self.namespace.min_similarity_lines
    # Cache hash_lineset results: each lineset is compared against every
    # other, so without caching it gets hashed (N-1) times.
    cache: dict[int, LineSetHashResult] = {}
    for idx, lineset1 in enumerate(self.linesets[:-1]):
        for lineset2 in self.linesets[idx + 1 :]:
            key1 = id(lineset1)
            if key1 not in cache:
                cache[key1] = hash_lineset(lineset1, min_lines)
            key2 = id(lineset2)
            if key2 not in cache:
                cache[key2] = hash_lineset(lineset2, min_lines)
            yield from self._find_common(
                lineset1, lineset2, cache[key1], cache[key2]
            )

@staticmethod
def _components(
    graph: _ComparisonGraph,
) -> dict[_ComparisonOperand, int]:
    """Group the operands that are already compared with one another.

    Two operands share a component when a path of comparisons runs between
    them, whichever way the edges point.
    """
    neighbors: dict[_ComparisonOperand, set[_ComparisonOperand]] = (
        collections.defaultdict(set)
    )
    for left, rights in graph.edges.items():
        for right in rights:
            neighbors[left].add(right)
            neighbors[right].add(left)

    components: dict[_ComparisonOperand, int] = {}
    for index, start in enumerate(list(graph.edges)):
        if start in components:
            continue
        to_visit = [start]
        while to_visit:
            operand = to_visit.pop()
            if operand in components:
                continue
            components[operand] = index
            to_visit.extend(neighbors.get(operand, ()))
    return components

